using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using QualifyAI.Domain;
using QualifyAI.Persistence.SqlServer;

namespace QualifyAI.Infrastructure.Demo;

public sealed record ScenarioInstallResult(string Scenario, int Prospects, int Campaigns, int Opportunities, int Meetings, int Tickets, int Automations);
public sealed record ScenarioResetResult(int DeletedProspects, int DeletedLists, int DeletedAgents, int DeletedContacts, int DeletedLeads, int DeletedOpportunities, int DeletedPipelines, int DeletedMeetings, int DeletedAutomations);
public sealed record ResetAndInstallResult(ScenarioResetResult Reset, ScenarioInstallResult Scenario);

public sealed class RealisticScenarioService(AppDbContext db)
{
    public async Task<ResetAndInstallResult> ResetAndInstallAsync(Guid tenantId, CancellationToken ct = default)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        return await strategy.ExecuteAsync(async () =>
        {
            db.ChangeTracker.Clear();
            await using var transaction = await db.Database.BeginTransactionAsync(ct);
            var reset = await ResetBusinessDataAsync(tenantId, ct);
            var scenario = await InstallAsync(tenantId, ct);
            await transaction.CommitAsync(ct);
            return new ResetAndInstallResult(reset, scenario);
        });
    }

    public async Task<ScenarioResetResult> ResetBusinessDataAsync(Guid tenantId, CancellationToken ct = default)
    {
        await DeleteAsync(db.ProspectReplies, tenantId, ct); await DeleteAsync(db.OutreachMessages, tenantId, ct); await DeleteAsync(db.CampaignRecipients, tenantId, ct); await DeleteAsync(db.CampaignSteps, tenantId, ct); await DeleteAsync(db.Campaigns, tenantId, ct); await DeleteAsync(db.TargetListMembers, tenantId, ct); var deletedLists=await DeleteAsync(db.TargetLists, tenantId, ct); await DeleteAsync(db.ProspectSignals, tenantId, ct); var deletedProspects=await DeleteAsync(db.Prospects, tenantId, ct); await DeleteAsync(db.IcpProfiles, tenantId, ct);
        await DeleteAsync(db.RevenueAttributions, tenantId, ct); await DeleteAsync(db.LeadScoreExplanations, tenantId, ct); await DeleteAsync(db.QualificationAnswers, tenantId, ct); await DeleteAsync(db.CrmTasks, tenantId, ct); await DeleteAsync(db.CrmActivitys, tenantId, ct); var deletedOpportunities=await DeleteAsync(db.Opportunitys, tenantId, ct); var deletedLeads=await DeleteAsync(db.Leads, tenantId, ct); var deletedContacts=await DeleteAsync(db.Contacts, tenantId, ct); await DeleteAsync(db.Companys, tenantId, ct); var deletedMeetings=await DeleteAsync(db.MeetingBookings, tenantId, ct); await DeleteAsync(db.MeetingTypes, tenantId, ct); var deletedPipelines=await DeleteAsync(db.PipelineStages, tenantId, ct); deletedPipelines+=await DeleteAsync(db.Pipelines, tenantId, ct);
        await DeleteAsync(db.AiToolExecutions, tenantId, ct); await DeleteAsync(db.AiAgentVersions, tenantId, ct); var deletedAgents=await DeleteAsync(db.AiAgents, tenantId, ct); await DeleteAsync(db.AiToolDefinitions, tenantId, ct); await DeleteAsync(db.PromptVersions, tenantId, ct); await DeleteAsync(db.WorkflowEdges, tenantId, ct); await DeleteAsync(db.WorkflowNodes, tenantId, ct); await DeleteAsync(db.QualificationFlows, tenantId, ct); var deletedAutomations=await DeleteAsync(db.AutomationRuns, tenantId, ct); deletedAutomations+=await DeleteAsync(db.AutomationRules, tenantId, ct);
        await DeleteAsync(db.TicketEvents, tenantId, ct); await DeleteAsync(db.CsatResponses, tenantId, ct); await DeleteAsync(db.ConversationNotes, tenantId, ct); await DeleteAsync(db.Messages, tenantId, ct); await DeleteAsync(db.Conversations, tenantId, ct); await DeleteAsync(db.Channels, tenantId, ct); await DeleteAsync(db.Tickets, tenantId, ct); await DeleteAsync(db.KnowledgeGaps, tenantId, ct); await DeleteAsync(db.MetricSnapshots, tenantId, ct); await DeleteAsync(db.Notifications, tenantId, ct);
        return new ScenarioResetResult(deletedProspects, deletedLists, deletedAgents, deletedContacts, deletedLeads, deletedOpportunities, deletedPipelines, deletedMeetings, deletedAutomations);
    }
    private static Task<int> DeleteAsync<TEntity>(DbSet<TEntity> set, Guid tenantId, CancellationToken ct) where TEntity:TenantEntity => set.Where(x=>x.TenantId==tenantId).ExecuteDeleteAsync(ct);

    public async Task<ScenarioInstallResult> InstallAsync(Guid tenantId, CancellationToken ct=default)
    {
        await EnsureFusionFleetScenarioAsync(tenantId, ct);
        await EnsureQualifyAiScenarioAsync(tenantId, ct);
        var now=DateTime.UtcNow;
        await EnsureSupportScenarioAsync(tenantId, now, ct);
        await EnsureAgentsAsync(tenantId, ct);
        await db.SaveChangesAsync(ct);
        return await SnapshotAsync(tenantId, "FusionFleet and QualifyAI customer acquisition + controlled support operations", ct);
    }

    public async Task<ScenarioInstallResult> InstallFusionFleetPackageAsync(Guid tenantId, CancellationToken ct=default)
    {
        await EnsureFusionFleetScenarioAsync(tenantId, ct);
        await db.SaveChangesAsync(ct);
        return await SnapshotAsync(tenantId, "FusionFleet Promotion", ct);
    }

    public async Task<ScenarioInstallResult> InstallQualifyAiAcquisitionPackageAsync(Guid tenantId, CancellationToken ct=default)
    {
        await EnsureQualifyAiScenarioAsync(tenantId, ct);
        await db.SaveChangesAsync(ct);
        return await SnapshotAsync(tenantId, "QualifyAI Acquisition", ct);
    }

    private async Task<ScenarioInstallResult> SnapshotAsync(Guid tenantId,string scenario,CancellationToken ct)=>new(scenario,await db.Prospects.CountAsync(x=>x.TenantId==tenantId,ct),await db.Campaigns.CountAsync(x=>x.TenantId==tenantId,ct),await db.Opportunitys.CountAsync(x=>x.TenantId==tenantId,ct),await db.MeetingBookings.CountAsync(x=>x.TenantId==tenantId,ct),await db.Tickets.CountAsync(x=>x.TenantId==tenantId,ct),await db.AutomationRules.CountAsync(x=>x.TenantId==tenantId,ct));

    private async Task EnsureFusionFleetScenarioAsync(Guid tenantId,CancellationToken ct)
    {
        var now=DateTime.UtcNow; const string icpName="[PRESENTATION] FusionFleet — EU logistics growth";
        var icp=await db.IcpProfiles.FirstOrDefaultAsync(x=>x.TenantId==tenantId&&x.Name==icpName,ct);
        if(icp is null){icp=new IcpProfile{TenantId=tenantId,Name=icpName,Industry="Logistics, Distribution, Manufacturing, E-commerce",CountriesCsv="Germany, France, Italy",MinimumEmployees=20,MaximumEmployees=1000,IntentKeywordsCsv="freight tender, warehouse expansion, fleet growth, delivery delays",CriteriaJson="{\"requiredSignals\":1,\"minimumFitScore\":70}",Active=true,LastDiscoveryAtUtc=now};db.IcpProfiles.Add(icp);}
        var seeds=new[]{new ProspectSeed("NordCargo Solutions","nordcargo.example","Lukas Meyer","Head of Operations","lukas.meyer@nordcargo.example","Logistics","Germany",92,81,"Published a freight technology tender after expanding its cross-border fleet."),new ProspectSeed("RheinFulfil GmbH","rheinfulfil.example","Anna Fischer","VP Supply Chain","anna.fischer@rheinfulfil.example","E-commerce","Germany",89,74,"Hiring warehouse systems specialists for a new fulfilment location."),new ProspectSeed("Atlas Components","atlascomponents.example","Sofia Romano","Logistics Director","sofia.romano@atlascomponents.example","Manufacturing","Italy",91,69,"Announced distribution expansion into two additional regions."),new ProspectSeed("BlueLine 3PL","blueline3pl.example","Marc Dubois","Managing Director","marc.dubois@blueline3pl.example","Logistics","France",88,84,"Customer reviews indicate recurring shipment visibility and delivery-delay issues."),new ProspectSeed("Milano Distribution","milanodistribution.example","Giulia Conti","Warehouse Director","giulia.conti@milanodistribution.example","Distribution","Italy",86,77,"Opened a second warehouse and increased transport coordinator hiring.")};
        var prospects=await db.Prospects.Where(x=>x.TenantId==tenantId&&x.Source=="presentation-scenario"&&x.DatasetOrigin=="FusionFleet presentation scenario").ToListAsync(ct);
        if(prospects.Count==0)foreach(var s in seeds){var p=new Prospect{TenantId=tenantId,CompanyName=s.Company,Domain=s.Domain,ContactName=s.Contact,JobTitle=s.JobTitle,Email=s.Email,Industry=s.Industry,Country=s.Country,Source="presentation-scenario",Priority="A",ContactReadiness="Demo ready",SuggestedBuyer=s.JobTitle,PainHypothesis=s.Evidence,Offer="FusionFleet operational platform pilot",SourceUrl=$"https://signals.example/{s.Domain}",VerificationStatus="Presentation scenario",OutreachStatus="Ready for approval",DatasetOrigin="FusionFleet presentation scenario"};p.Evaluate(s.Fit,s.Intent);db.Prospects.Add(p);prospects.Add(p);db.ProspectSignals.Add(new ProspectSignal{TenantId=tenantId,ProspectId=p.Id,Type="presentation-buying-intent",Source="presentation-scenario",Evidence=s.Evidence,Score=s.Intent,SourceUrl=p.SourceUrl});}
        var list=await db.TargetLists.FirstOrDefaultAsync(x=>x.TenantId==tenantId&&x.Name=="[PRESENTATION] FusionFleet — EU logistics accounts",ct); if(list is null){list=new TargetList{TenantId=tenantId,IcpProfileId=icp.Id,Name="[PRESENTATION] FusionFleet — EU logistics accounts",Description="FusionFleet presentation accounts."};db.TargetLists.Add(list);} foreach(var p in prospects)if(!await db.TargetListMembers.AnyAsync(x=>x.TenantId==tenantId&&x.TargetListId==list.Id&&x.ProspectId==p.Id,ct))db.TargetListMembers.Add(new TargetListMember{TenantId=tenantId,TargetListId=list.Id,ProspectId=p.Id});
        var campaign=await db.Campaigns.FirstOrDefaultAsync(x=>x.TenantId==tenantId&&x.Name=="[PRESENTATION] FusionFleet — book operational demo",ct); if(campaign is null){campaign=new Campaign{TenantId=tenantId,TargetListId=list.Id,Name="[PRESENTATION] FusionFleet — book operational demo",Goal="book-demo",Status=CampaignStatus.Running,SenderName="FusionFleet Growth",SenderEmail="growth@fusionfleet.example",StartsAtUtc=now.AddDays(-5)};db.Campaigns.Add(campaign);db.CampaignSteps.Add(new CampaignStep{TenantId=tenantId,CampaignId=campaign.Id,StepNumber=1,DelayHours=0,Channel="email",SubjectTemplate="{{company}}: reduce dispatch and delivery exceptions",BodyTemplate="Hi {{contact}}, I noticed current growth signals at {{company}}. Would a 25-minute operational demo be useful?"});}
        foreach(var p in prospects)if(!await db.CampaignRecipients.AnyAsync(x=>x.TenantId==tenantId&&x.CampaignId==campaign.Id&&x.ProspectId==p.Id,ct))db.CampaignRecipients.Add(new CampaignRecipient{TenantId=tenantId,CampaignId=campaign.Id,ProspectId=p.Id,Status="active",NextRunAtUtc=now});
        var stage=await EnsurePipelineAsync(tenantId,"FusionFleet revenue pipeline",true,ct); await EnsureConvertedJourneyAsync(tenantId,prospects[0],campaign,stage,now,ct); await EnsureFusionFleetAutomationAsync(tenantId,icp.Id,ct); await EnsureAgentAsync(tenantId,"FusionFleet prospecting agent","Logistics market researcher","Review logistics prospect evidence, preserve verification notes and route only qualified, approval-ready accounts into the FusionFleet campaign.","en,de,it,fr",ct);
    }

    private async Task EnsureQualifyAiScenarioAsync(Guid tenantId,CancellationToken ct)
    {
        var now=DateTime.UtcNow; const string icpName="[PRESENTATION] QualifyAI B2B revenue operations"; var icp=await db.IcpProfiles.FirstOrDefaultAsync(x=>x.TenantId==tenantId&&x.Name==icpName,ct); if(icp is null){icp=new IcpProfile{TenantId=tenantId,Name=icpName,Industry="B2B SaaS, professional services, operations",CountriesCsv="Germany, France, United Kingdom",MinimumEmployees=20,MaximumEmployees=2000,IntentKeywordsCsv="manual qualification, slow follow-up, fragmented customer requests",CriteriaJson="{\"requiredSignals\":1,\"minimumFitScore\":70}",Active=true,LastDiscoveryAtUtc=now};db.IcpProfiles.Add(icp);} var s=new ProspectSeed("Cobalt Operations Cloud","cobalt-operations.example","Elena Brooks","VP Revenue Operations","elena.brooks@cobalt-operations.example","B2B SaaS","United Kingdom",93,82,"Announced a revenue operations hiring plan and a need to standardize lead qualification."); var p=await db.Prospects.FirstOrDefaultAsync(x=>x.TenantId==tenantId&&x.Domain==s.Domain,ct); if(p is null){p=new Prospect{TenantId=tenantId,CompanyName=s.Company,Domain=s.Domain,ContactName=s.Contact,JobTitle=s.JobTitle,Email=s.Email,Industry=s.Industry,Country=s.Country,Source="presentation-scenario",Priority="A",ContactReadiness="Demo ready",SuggestedBuyer=s.JobTitle,PainHypothesis="Qualification and follow-up are fragmented across spreadsheets and inboxes.",Offer="QualifyAI revenue operations pilot",SourceUrl="https://example.com/cobalt-operations",VerificationStatus="Presentation scenario",OutreachStatus="Ready for approval",DatasetOrigin="QualifyAI presentation scenario"};p.Evaluate(s.Fit,s.Intent);db.Prospects.Add(p);db.ProspectSignals.Add(new ProspectSignal{TenantId=tenantId,ProspectId=p.Id,Type="revenue-operations",Source="presentation-scenario",Evidence=s.Evidence,Score=s.Intent,SourceUrl=p.SourceUrl});}
        var list=await db.TargetLists.FirstOrDefaultAsync(x=>x.TenantId==tenantId&&x.Name=="[PRESENTATION] QualifyAI revenue operations accounts",ct);if(list is null){list=new TargetList{TenantId=tenantId,IcpProfileId=icp.Id,Name="[PRESENTATION] QualifyAI revenue operations accounts",Description="Presentation accounts for the QualifyAI go-to-market pipeline."};db.TargetLists.Add(list);}if(!await db.TargetListMembers.AnyAsync(x=>x.TenantId==tenantId&&x.TargetListId==list.Id&&x.ProspectId==p.Id,ct))db.TargetListMembers.Add(new TargetListMember{TenantId=tenantId,TargetListId=list.Id,ProspectId=p.Id}); var campaign=await db.Campaigns.FirstOrDefaultAsync(x=>x.TenantId==tenantId&&x.Name=="[PRESENTATION] QualifyAI — revenue operations pilot",ct);if(campaign is null){campaign=new Campaign{TenantId=tenantId,TargetListId=list.Id,Name="[PRESENTATION] QualifyAI — revenue operations pilot",Goal="book-demo",Status=CampaignStatus.Running,SenderName="QualifyAI Growth",SenderEmail="growth@qualifyai.example",StartsAtUtc=now.AddDays(-4)};db.Campaigns.Add(campaign);db.CampaignSteps.Add(new CampaignStep{TenantId=tenantId,CampaignId=campaign.Id,StepNumber=1,DelayHours=0,Channel="email",SubjectTemplate="{{company}}: turn qualified demand into booked demos",BodyTemplate="Hi {{contact}}, QualifyAI connects discovery, qualification and controlled outreach. Would a 25-minute walkthrough be useful?"});}if(!await db.CampaignRecipients.AnyAsync(x=>x.TenantId==tenantId&&x.CampaignId==campaign.Id&&x.ProspectId==p.Id,ct))db.CampaignRecipients.Add(new CampaignRecipient{TenantId=tenantId,CampaignId=campaign.Id,ProspectId=p.Id,Status="replied",RepliedAtUtc=now.AddHours(-8)});var stage=await EnsurePipelineAsync(tenantId,"QualifyAI revenue pipeline",false,ct);var company=await db.Companys.FirstOrDefaultAsync(x=>x.TenantId==tenantId&&x.Domain==p.Domain,ct);if(company is null){company=Company.Create(tenantId,p.CompanyName,p.Domain,p.Industry,120,p.Country,12_000_000m);db.Companys.Add(company);}var contact=await db.Contacts.FirstOrDefaultAsync(x=>x.TenantId==tenantId&&x.Email==p.Email,ct);if(contact is null){contact=Contact.Create(tenantId,company.Id,"Elena","Brooks",p.Email,"+44 20 7946 0184","sql");db.Contacts.Add(contact);}var lead=await db.Leads.FirstOrDefaultAsync(x=>x.TenantId==tenantId&&x.ContactId==contact.Id,ct);if(lead is null){lead=Lead.Create(tenantId,contact.Id,company.Id,"outbound-campaign",93,36_000m,"Revenue operations team requested a product walkthrough.");lead.Qualify();db.Leads.Add(lead);}if(!await db.Opportunitys.AnyAsync(x=>x.TenantId==tenantId&&x.LeadId==lead.Id,ct))db.Opportunitys.Add(new Opportunity{TenantId=tenantId,LeadId=lead.Id,CompanyId=company.Id,ContactId=contact.Id,PipelineStageId=stage.Id,Name="Cobalt Operations — QualifyAI revenue operations pilot",Amount=36_000m,ExpectedCloseUtc=now.AddDays(21)});var mt=await db.MeetingTypes.FirstOrDefaultAsync(x=>x.TenantId==tenantId&&x.Name=="Revenue operations walkthrough",ct);if(mt is null){mt=new MeetingType{TenantId=tenantId,Name="Revenue operations walkthrough",DurationMinutes=30,LocationType="video"};db.MeetingTypes.Add(mt);}if(!await db.MeetingBookings.AnyAsync(x=>x.TenantId==tenantId&&x.LeadId==lead.Id,ct))db.MeetingBookings.Add(new MeetingBooking{TenantId=tenantId,MeetingTypeId=mt.Id,ContactId=contact.Id,LeadId=lead.Id,StartsAtUtc=now.AddDays(2).Date.AddHours(14),EndsAtUtc=now.AddDays(2).Date.AddHours(14.5),Status="booked",ExternalEventId="qualifyai-revenue-ops-demo"});await EnsureQualifyAiAutomationAsync(tenantId,ct);await EnsureAgentAsync(tenantId,"QualifyAI revenue operations agent","B2B revenue qualification","Turn verified demand signals into qualified leads, a controlled outreach draft, a demo booking and an opportunity with a clear next step.","en,de,fr",ct);
