    private async Task<PipelineStage> EnsurePipelineAsync(Guid tenantId,string name,bool isDefault,CancellationToken ct){var pipeline=await db.Pipelines.FirstOrDefaultAsync(x=>x.TenantId==tenantId&&x.Name==name,ct);if(pipeline is null){pipeline=new Pipeline{TenantId=tenantId,Name=name,IsDefault=isDefault};db.Pipelines.Add(pipeline);db.PipelineStages.AddRange(new PipelineStage{TenantId=tenantId,PipelineId=pipeline.Id,Name="Qualified",SortOrder=1,Probability=30},new PipelineStage{TenantId=tenantId,PipelineId=pipeline.Id,Name="Discovery demo",SortOrder=2,Probability=55},new PipelineStage{TenantId=tenantId,PipelineId=pipeline.Id,Name="Proposal",SortOrder=3,Probability=75},new PipelineStage{TenantId=tenantId,PipelineId=pipeline.Id,Name="Won",SortOrder=4,Probability=100});}return db.PipelineStages.Local.FirstOrDefault(x=>x.TenantId==tenantId&&x.PipelineId==pipeline.Id&&x.Name=="Discovery demo")??await db.PipelineStages.FirstOrDefaultAsync(x=>x.TenantId==tenantId&&x.PipelineId==pipeline.Id&&x.Name=="Discovery demo",ct)??throw new InvalidOperationException("The presentation pipeline stage could not be created.");}
    private async Task EnsureConvertedJourneyAsync(Guid tenantId,Prospect prospect,Campaign campaign,PipelineStage stage,DateTime now,CancellationToken ct){var company=await db.Companys.FirstOrDefaultAsync(x=>x.TenantId==tenantId&&x.Domain==prospect.Domain,ct);if(company is null){company=Company.Create(tenantId,prospect.CompanyName,prospect.Domain,prospect.Industry,86,prospect.Country,18_400_000m);db.Companys.Add(company);}var contact=await db.Contacts.FirstOrDefaultAsync(x=>x.TenantId==tenantId&&x.Email==prospect.Email,ct);if(contact is null){var names=prospect.ContactName.Split(' ',2);contact=Contact.Create(tenantId,company.Id,names[0],names.Length>1?names[1]:"",prospect.Email,"+49 30 555 0142","sql");db.Contacts.Add(contact);}var lead=await db.Leads.FirstOrDefaultAsync(x=>x.TenantId==tenantId&&x.ContactId==contact.Id,ct);if(lead is null){lead=Lead.Create(tenantId,contact.Id,company.Id,"outbound-campaign",94,48_000m,"Fleet expansion and freight technology tender; interested reply received.");lead.Qualify();db.Leads.Add(lead);}var opp=await db.Opportunitys.FirstOrDefaultAsync(x=>x.TenantId==tenantId&&x.LeadId==lead.Id,ct);if(opp is null){opp=new Opportunity{TenantId=tenantId,LeadId=lead.Id,CompanyId=company.Id,ContactId=contact.Id,PipelineStageId=stage.Id,Name="NordCargo operational platform rollout",Amount=48_000m,Status=OpportunityStatus.Open,ExpectedCloseUtc=now.AddDays(28)};db.Opportunitys.Add(opp);}var mt=await db.MeetingTypes.FirstOrDefaultAsync(x=>x.TenantId==tenantId&&x.Name=="Operational discovery demo",ct);if(mt is null){mt=new MeetingType{TenantId=tenantId,Name="Operational discovery demo",DurationMinutes=30,LocationType="video"};db.MeetingTypes.Add(mt);}if(!await db.MeetingBookings.AnyAsync(x=>x.TenantId==tenantId&&x.LeadId==lead.Id,ct))db.MeetingBookings.Add(new MeetingBooking{TenantId=tenantId,MeetingTypeId=mt.Id,ContactId=contact.Id,LeadId=lead.Id,StartsAtUtc=now.AddDays(3).Date.AddHours(10),EndsAtUtc=now.AddDays(3).Date.AddHours(10.5),Status="booked",ExternalEventId="demo-calendar-event"});if(!await db.ProspectReplies.AnyAsync(x=>x.TenantId==tenantId&&x.CampaignId==campaign.Id&&x.ProspectId==prospect.Id,ct)){var recipient=db.CampaignRecipients.Local.FirstOrDefault(x=>x.TenantId==tenantId&&x.CampaignId==campaign.Id&&x.ProspectId==prospect.Id)??await db.CampaignRecipients.FirstOrDefaultAsync(x=>x.TenantId==tenantId&&x.CampaignId==campaign.Id&&x.ProspectId==prospect.Id,ct);if(recipient is not null){recipient.Status="replied";recipient.RepliedAtUtc=now.AddDays(-1);recipient.NextRunAtUtc=null;}db.ProspectReplies.Add(new ProspectReply{TenantId=tenantId,CampaignId=campaign.Id,ProspectId=prospect.Id,Body="Yes, visibility across dispatch and delivery exceptions is a priority.",Classification="interested",SentimentScore=91,RequiresHuman=true,ReceivedAtUtc=now.AddDays(-1)});prospect.Status=ProspectStatus.DemoReady;}}
    private async Task EnsureFusionFleetAutomationAsync(Guid tenantId,Guid icpId,CancellationToken ct){var flow=await db.QualificationFlows.FirstOrDefaultAsync(x=>x.TenantId==tenantId&&x.Name=="Find FusionFleet Customers & Book Demos",ct);if(flow is null){flow=new QualificationFlow{TenantId=tenantId,Name="Find FusionFleet Customers & Book Demos",Active=true};db.QualificationFlows.Add(flow);db.WorkflowNodes.AddRange(WorkflowNode.Create(tenantId,flow.Id,"schedule","start","{\"trigger\":\"daily\"}",60,160),WorkflowNode.Create(tenantId,flow.Id,"discover","discoverProspects",$"{{\"source\":\"serpapi\",\"icpId\":\"{icpId}\"}}",300,160),WorkflowNode.Create(tenantId,flow.Id,"score","score","{\"points\":75}",540,160),WorkflowNode.Create(tenantId,flow.Id,"campaign","email","{\"template\":\"logistics-growth\"}",780,160));}}
