    private async Task EnsureSupportScenarioAsync(Guid tenantId,DateTime now,CancellationToken ct){if(!await db.Tickets.AnyAsync(x=>x.TenantId==tenantId&&x.Number=="T-DEMO-DELIVERY",ct))db.Tickets.Add(new Ticket{TenantId=tenantId,Number="T-DEMO-DELIVERY",Subject="Cross-border delivery delayed",Description="Customer contract includes priority delivery support. Shipment has not updated for 18 hours.",Status=TicketStatus.Open,Priority=TicketPriority.High,FirstResponseDueUtc=now.AddMinutes(25),ResolutionDueUtc=now.AddHours(4)});if(!await db.Tickets.AnyAsync(x=>x.TenantId==tenantId&&x.Number=="T-DEMO-PAYMENT",ct))db.Tickets.Add(new Ticket{TenantId=tenantId,Number="T-DEMO-PAYMENT",Subject="Duplicate payment transaction",Description="Customer reports two captures for the same invoice.",Status=TicketStatus.Pending,Priority=TicketPriority.Urgent,FirstResponseDueUtc=now.AddMinutes(10),ResolutionDueUtc=now.AddHours(2)});}
